missions.solution:
static void springe() {
    robot.turnLeft();
    robot.move();
    robot.turnRight();
    robot.move();
    robot.move();
    robot.turnRight();
    robot.move();
    robot.turnLeft();
}

while (!robot.atGoal()) {
    if (robot.frontIsClear()) {
        robot.move();
        if (robot.onCoin()) robot.pickCoin();
    } else {
        springe();
    }
}

