missions.solution:
static void schritt() {
    if (robot.rightIsClear()) {
        robot.turnRight();
        robot.move();
    } else if (robot.frontIsClear()) {
        robot.move();
    } else {
        robot.turnLeft();
    }
}

while (!robot.atGoal()) {
    schritt();
    if (robot.onCoin()) {
        robot.pickCoin();
    }
}

int[] strecken = {4, 3, 2};
for (int strecke : strecken) {
    for (int i = 0; i < strecke; i++) {
        robot.move();
        if (robot.onCoin()) {
            robot.pickCoin();
        }
    }
    robot.turnLeft();
}

